"use client";

import { useEffect, useRef } from "react";
import "./changed-digit-roll.css";

export interface ChangedDigitRollProps {
  value: number;
  label: string;
  locale?: string;
  maximumFractionDigits?: number;
  prefix?: string;
  suffix?: string;
  className?: string;
}

export function ChangedDigitRoll({
  value,
  label,
  locale = "en-US",
  maximumFractionDigits = 0,
  prefix = "",
  suffix = "",
  className = "",
}: ChangedDigitRollProps) {
  const safeValue = Number.isFinite(value) ? value : 0;
  const formatter = new Intl.NumberFormat(locale, { maximumFractionDigits });
  const formatted = formatter.format(safeValue);
  const previousText = useRef(formatted);
  const previousValue = useRef(safeValue);
  const prior = previousText.current;
  const direction = safeValue >= previousValue.current ? "up" : "down";
  const width = Math.max(prior.length, formatted.length);
  const oldCharacters = prior.padStart(width, "\u00a0").split("");
  const newCharacters = formatted.padStart(width, "\u00a0").split("");

  useEffect(() => {
    previousText.current = formatted;
    previousValue.current = safeValue;
  }, [formatted, safeValue]);

  return (
    <span
      className={`tb-changed-digit-roll ${className}`.trim()}
      data-direction={direction}
    >
      <span className="tb-changed-digit-roll__sr" role="status" aria-live="polite">
        {label}: {prefix}{formatted}{suffix}
      </span>
      <span className="tb-changed-digit-roll__visual" aria-hidden="true">
        {prefix ? <span>{prefix}</span> : null}
        {newCharacters.map((character, index) => {
          const oldCharacter = oldCharacters[index];
          const changed =
            character !== oldCharacter && /\d/.test(character) && /\d/.test(oldCharacter);

          return changed ? (
            <span
              className="tb-changed-digit-roll__character tb-changed-digit-roll__character--changed"
              key={`${formatted}-${index}-${character}`}
            >
              <span className="tb-changed-digit-roll__old">{oldCharacter}</span>
              <span className="tb-changed-digit-roll__new">{character}</span>
            </span>
          ) : (
            <span className="tb-changed-digit-roll__character" key={`${index}-${character}`}>
              {character}
            </span>
          );
        })}
        {suffix ? <span>{suffix}</span> : null}
      </span>
    </span>
  );
}

export default ChangedDigitRoll;

.tb-changed-digit-roll {
  display: inline-block;
  color: #191b22;
  font: 680 clamp(3rem, 12cqi, 7rem) / 0.9 ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.08em;
}

.tb-changed-digit-roll__visual {
  display: inline-flex;
  align-items: baseline;
}

.tb-changed-digit-roll__character {
  display: inline-grid;
  min-width: 0.62em;
  justify-items: center;
}

.tb-changed-digit-roll__character--changed {
  position: relative;
  height: 0.94em;
  overflow: hidden;
  vertical-align: -0.04em;
}

.tb-changed-digit-roll__old,
.tb-changed-digit-roll__new {
  grid-area: 1 / 1;
}

.tb-changed-digit-roll[data-direction="up"] .tb-changed-digit-roll__old {
  animation: tb-digit-old-up 160ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.tb-changed-digit-roll[data-direction="up"] .tb-changed-digit-roll__new {
  animation: tb-digit-new-up 160ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.tb-changed-digit-roll[data-direction="down"] .tb-changed-digit-roll__old {
  animation: tb-digit-old-down 160ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.tb-changed-digit-roll[data-direction="down"] .tb-changed-digit-roll__new {
  animation: tb-digit-new-down 160ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.tb-changed-digit-roll__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@keyframes tb-digit-old-up {
  to { opacity: 0; transform: translateY(-100%); }
}

@keyframes tb-digit-new-up {
  from { opacity: 0; transform: translateY(100%); }
}

@keyframes tb-digit-old-down {
  to { opacity: 0; transform: translateY(100%); }
}

@keyframes tb-digit-new-down {
  from { opacity: 0; transform: translateY(-100%); }
}

@media (prefers-reduced-motion: reduce) {
  .tb-changed-digit-roll__old {
    display: none;
  }

  .tb-changed-digit-roll__new {
    animation: none !important;
  }
}

@media (forced-colors: active) {
  .tb-changed-digit-roll {
    color: CanvasText;
  }
}
